def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        return None

    def best_by(items, score_fn, default=None):
        best_item = default
        best_score = None
        for item in items:
            sc = score_fn(item)
            if best_score is None or sc < best_score:
                best_score = sc
                best_item = item
        return best_item

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pair(observation.get("self_position")) or [0, 0]
    opp_pos = first_pair(observation.get("opponent_position")) or self_pos[:]
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        target = best_by(corners, lambda c: dist(c, opp_pos), corners[0])
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        pairs = []
        for item in targets:
            p = first_pair(item)
            if p is not None:
                pairs.append(p)
        if pairs:
            target = best_by(pairs, lambda p: dist(p, self_pos), pairs[0])
            return step_toward(self_pos, target)
        center = [w // 2 if w else self_pos[0], h // 2 if h else self_pos[1]]
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    pairs = []
    for item in resources:
        p = first_pair(item)
        if p is not None:
            pairs.append(p)
    if pairs:
        target = best_by(pairs, lambda p: dist(p, self_pos), pairs[0])
        move = step_toward(self_pos, target)
        if move == step_toward(self_pos, opp_pos) and len(pairs) > 1:
            far = best_by(pairs, lambda p: dist(p, opp_pos) - dist(p, self_pos), pairs[0])
            move = step_toward(self_pos, far)
        return move

    if w and h:
        center = [w // 2, h // 2]
        return step_toward(self_pos, center)
    return [0, 0]

